     1→"use server";
     2→
     3→import { authAction } from "@/lib/actions/safe-actions";
     4→import { ActionError } from "@/lib/errors/action-error";
     5→import { prisma } from "@/lib/prisma";
     6→import { z } from "zod";
     7→
     8→const createMoodEntrySchema = z.object({
     9→  value: z.number().min(0).max(10),
    10→  note: z.string().optional(),
    11→});
    12→
    13→const updateMoodEntrySchema = z.object({
    14→  id: z.string(),
    15→  value: z.number().min(0).max(10),
    16→  note: z.string().optional(),
    17→});
    18→
    19→const deleteMoodEntrySchema = z.object({
    20→  id: z.string(),
    21→});
    22→
    23→const getMoodEntriesSchema = z.object({
    24→  days: z.number().optional(), // Filter by last N days
    25→  limit: z.number().optional().default(50),
    26→  cursor: z.string().optional(), // For pagination
    27→});
    28→
    29→export const createMoodEntry = authAction
    30→  .inputSchema(createMoodEntrySchema)
    31→  .action(async ({ parsedInput: { value, note }, ctx: { user } }) => {
    32→    const moodEntry = await prisma.moodEntry.create({
    33→      data: {
    34→        userId: user.id,
    35→        value,
    36→        note: note ?? null,
    37→        syncStatus: "synced",
    38→      },
    39→    });
    40→
    41→    return moodEntry;
    42→  });
    43→
    44→export const updateMoodEntry = authAction
    45→  .inputSchema(updateMoodEntrySchema)
    46→  .action(async ({ parsedInput: { id, value, note }, ctx: { user } }) => {
    47→    // Verify ownership
    48→    const existing = await prisma.moodEntry.findUnique({
    49→      where: { id },
    50→      select: { userId: true },
    51→    });
    52→
    53→    if (!existing) {
    54→      throw new ActionError("Mood entry not found");
    55→    }
    56→
    57→    if (existing.userId !== user.id) {
    58→      throw new ActionError("You can only edit your own mood entries");
    59→    }
    60→
    61→    const moodEntry = await prisma.moodEntry.update({
    62→      where: { id },
    63→      data: {
    64→        value,
    65→        note: note ?? null,
    66→      },
    67→    });
    68→
    69→    return moodEntry;
    70→  });
    71→
    72→export const deleteMoodEntry = authAction
    73→  .inputSchema(deleteMoodEntrySchema)
    74→  .action(async ({ parsedInput: { id }, ctx: { user } }) => {
    75→    // Verify ownership
    76→    const existing = await prisma.moodEntry.findUnique({
    77→      where: { id },
    78→      select: { userId: true },
    79→    });
    80→
    81→    if (!existing) {
    82→      throw new ActionError("Mood entry not found");
    83→    }
    84→
    85→    if (existing.userId !== user.id) {
    86→      throw new ActionError("You can only delete your own mood entries");
    87→    }
    88→
    89→    await prisma.moodEntry.delete({
    90→      where: { id },
    91→    });
    92→
    93→    return { success: true };
    94→  });
    95→
    96→export const getMoodEntries = authAction
    97→  .inputSchema(getMoodEntriesSchema)
    98→  .action(async ({ parsedInput: { days, limit, cursor }, ctx: { user } }) => {
    99→    const where: { userId: string; createdAt?: { gte: Date } } = {
   100→      userId: user.id,
   101→    };
   102→
   103→    // Filter by date range
   104→    if (days) {
   105→      const startDate = new Date();
   106→      startDate.setDate(startDate.getDate() - days);
   107→      where.createdAt = { gte: startDate };
   108→    }
   109→
   110→    const entries = await prisma.moodEntry.findMany({
   111→      where,
   112→      orderBy: { createdAt: "desc" },
   113→      take: limit + 1, // Take one extra to check if there are more
   114→      ...(cursor && {
   115→        cursor: { id: cursor },
   116→        skip: 1,
   117→      }),
   118→    });
   119→
   120→    const hasMore = entries.length > limit;
   121→    const data = hasMore ? entries.slice(0, -1) : entries;
   122→    const nextCursor = hasMore ? data[data.length - 1]?.id : undefined;
   123→
   124→    return {
   125→      entries: data,
   126→      nextCursor,
   127→      hasMore,
   128→    };
   129→  });
   130→
   131→// ===== Get Today's Mood Entry =====
   132→
   133→export const getTodayMoodEntry = authAction.action(
   134→  async ({ ctx: { user } }) => {
   135→    const startOfDay = new Date();
   136→    startOfDay.setHours(0, 0, 0, 0);
   137→
   138→    const entry = await prisma.moodEntry.findFirst({
   139→      where: {
   140→        userId: user.id,
   141→        createdAt: { gte: startOfDay },
   142→      },
   143→      orderBy: { createdAt: "desc" },
   144→      select: {
   145→        id: true,
   146→        value: true,
   147→        createdAt: true,
   148→      },
   149→    });
   150→
   151→    if (!entry) {
   152→      throw new ActionError("No mood entry for today");
   153→    }
   154→
   155→    return {
   156→      id: entry.id,
   157→      value: entry.value,
   158→      createdAt: entry.createdAt.toISOString(),
   159→    };
   160→  },
   161→);
   162→
   163→// ===== Save Mood Entry (Create or Update Today's) =====
   164→
   165→const saveMoodEntrySchema = z.object({
   166→  value: z.number().min(0).max(10),
   167→  note: z.string().optional(),
   168→});
   169→
   170→export const saveMoodEntry = authAction
   171→  .inputSchema(saveMoodEntrySchema)
   172→  .action(async ({ parsedInput: { value, note }, ctx: { user } }) => {
   173→    // Create a new entry (user can have multiple entries per day)
   174→    const entry = await prisma.moodEntry.create({
   175→      data: {
   176→        userId: user.id,
   177→        value,
   178→        note: note ?? null,
   179→        syncStatus: "synced",
   180→      },
   181→      select: {
   182→        id: true,
   183→        value: true,
   184→        createdAt: true,
   185→      },
   186→    });
   187→
   188→    return {
   189→      id: entry.id,
   190→      value: entry.value,
   191→      createdAt: entry.createdAt.toISOString(),
   192→    };
   193→  });
