     8→const createMedicationSchema = z.object({
     9→  name: z.string().min(1, "Le nom est requis"),
    10→  dosage: z.string().min(1, "Le dosage est requis"),
    11→  frequency: z.enum(["daily", "twice_daily", "weekly", "prn"]),
    12→  isPRN: z.boolean().optional().default(false),
    13→});
    14→
    15→const updateMedicationSchema = z.object({
    16→  id: z.string(),
    17→  name: z.string().min(1, "Le nom est requis"),
    18→  dosage: z.string().min(1, "Le dosage est requis"),
    19→  frequency: z.enum(["daily", "twice_daily", "weekly", "prn"]),
    20→  isPRN: z.boolean().optional().default(false),
    21→});
    22→
    23→const getMedicationsSchema = z.object({
    24→  includeArchived: z.boolean().optional().default(false),
    25→});
    26→
    27→export const createMedication = authAction
    28→  .inputSchema(createMedicationSchema)
    29→  .action(
    30→    async ({
    31→      parsedInput: { name, dosage, frequency, isPRN },
    32→      ctx: { user },
    33→    }) => {
    34→      const medication = await prisma.medication.create({
    35→        data: {
    36→          userId: user.id,
    37→          name,
    38→          dosage,
    39→          frequency,
    40→          isPRN: isPRN || frequency === "prn",
    41→          syncStatus: "synced",
    42→        },
    43→      });
    44→
    45→      // Create initial history entry
    46→      await prisma.medicationHistory.create({
    47→        data: {
    48→          medicationId: medication.id,
    49→          dosage,
    50→          reason: "Initial dosage",
    51→        },
    52→      });
    53→
    54→      return medication;
    55→    },
    56→  );
    57→
    58→export const updateMedication = authAction
    59→  .inputSchema(updateMedicationSchema)
    60→  .action(
    61→    async ({
    62→      parsedInput: { id, name, dosage, frequency, isPRN },
    63→      ctx: { user },
    64→    }) => {
    65→      // Verify ownership
    66→      const existing = await prisma.medication.findUnique({
    67→        where: { id },
    68→        select: { userId: true, dosage: true },
    69→      });
    70→
    71→      if (!existing) {
    72→        throw new ActionError("Medication not found");
    73→      }
    74→
    75→      if (existing.userId !== user.id) {
    76→        throw new ActionError("You can only edit your own medications");
    77→      }
    78→
    79→      // Check if dosage changed
    80→      const dosageChanged = existing.dosage !== dosage;
    81→
    82→      const medication = await prisma.medication.update({
    83→        where: { id },
    84→        data: {
    85→          name,
    86→          dosage,
    87→          frequency,
    88→          isPRN: isPRN || frequency === "prn",
    89→        },
    90→      });
    91→
    92→      // Create history entry if dosage changed
    93→      if (dosageChanged) {
    94→        await prisma.medicationHistory.create({
    95→          data: {
    96→            medicationId: id,
    97→            dosage,
    98→            previousDosage: existing.dosage,
    99→            reason: "Dosage adjustment",
   100→          },
   101→        });
   102→      }
   103→
   104→      return medication;
   105→    },
   106→  );
