   108→export const archiveMedication = authAction
   109→  .inputSchema(z.object({ id: z.string() }))
   110→  .action(async ({ parsedInput: { id }, ctx: { user } }) => {
   111→    // Verify ownership
   112→    const existing = await prisma.medication.findUnique({
   113→      where: { id },
   114→      select: { userId: true },
   115→    });
   116→
   117→    if (!existing) {
   118→      throw new ActionError("Medication not found");
   119→    }
   120→
   121→    if (existing.userId !== user.id) {
   122→      throw new ActionError("You can only archive your own medications");
   123→    }
   124→
   125→    const medication = await prisma.medication.update({
   126→      where: { id },
   127→      data: { isArchived: true },
   128→    });
   129→
   130→    return medication;
   131→  });
   132→
   133→export const unarchiveMedication = authAction
   134→  .inputSchema(z.object({ id: z.string() }))
   135→  .action(async ({ parsedInput: { id }, ctx: { user } }) => {
   136→    // Verify ownership
   137→    const existing = await prisma.medication.findUnique({
   138→      where: { id },
   139→      select: { userId: true },
   140→    });
   141→
   142→    if (!existing) {
   143→      throw new ActionError("Medication not found");
   144→    }
   145→
   146→    if (existing.userId !== user.id) {
