   158→export const getMedications = authAction
   159→  .inputSchema(getMedicationsSchema)
   160→  .action(async ({ parsedInput: { includeArchived }, ctx: { user } }) => {
   161→    const medications = await prisma.medication.findMany({
   162→      where: {
   163→        userId: user.id,
   164→        ...(includeArchived ? {} : { isArchived: false }),
   165→      },
   166→      include: {
   167→        intakes: {
   168→          where: {
   169→            takenAt: {
   170→              gte: new Date(new Date().setHours(0, 0, 0, 0)), // Today
   171→            },
   172→          },
   173→          orderBy: { takenAt: "desc" },
   174→          take: 1,
   175→        },
   176→      },
   177→      orderBy: [{ isPRN: "asc" }, { name: "asc" }],
   178→    });
   179→
   180→    return medications;
   181→  });
