   183→export const getMedicationById = authAction
   184→  .inputSchema(z.object({ id: z.string() }))
   185→  .action(async ({ parsedInput: { id }, ctx: { user } }) => {
   186→    const medication = await prisma.medication.findUnique({
   187→      where: { id },
   188→      include: {
   189→        history: {
   190→          orderBy: { changedAt: "desc" },
   191→        },
   192→      },
   193→    });
   194→
   195→    if (!medication) {
   196→      throw new ActionError("Medication not found");
   197→    }
   198→
   199→    if (medication.userId !== user.id) {
   200→      throw new ActionError("You can only view your own medications");
   201→    }
   202→
   203→    return medication;
   204→  });
