   206→// ===== Medication Intake Actions =====
   207→
   208→const logIntakeSchema = z.object({
   209→  medicationId: z.string(),
   210→  note: z.string().optional(),
   211→});
   212→
   213→const skipIntakeSchema = z.object({
   214→  medicationId: z.string(),
