   222→export const logMedIntake = authAction
   223→  .inputSchema(logIntakeSchema)
   224→  .action(async ({ parsedInput: { medicationId, note }, ctx: { user } }) => {
   225→    // Verify medication ownership
   226→    const medication = await prisma.medication.findUnique({
   227→      where: { id: medicationId },
   228→      select: { userId: true },
   229→    });
   230→
   231→    if (!medication) {
   232→      throw new ActionError("Medication not found");
   233→    }
   234→
   235→    if (medication.userId !== user.id) {
   236→      throw new ActionError("You can only log intake for your own medications");
   237→    }
   238→
   239→    const intake = await prisma.medIntake.create({
   240→      data: {
   241→        medicationId,
   242→        takenAt: new Date(),
   243→        skipped: false,
   244→        note,
   245→      },
   246→    });
   247→
   248→    return intake;
   249→  });
