   251→export const skipMedIntake = authAction
   252→  .inputSchema(skipIntakeSchema)
   253→  .action(async ({ parsedInput: { medicationId, reason }, ctx: { user } }) => {
   254→    // Verify medication ownership
   255→    const medication = await prisma.medication.findUnique({
   256→      where: { id: medicationId },
   257→      select: { userId: true },
   258→    });
   259→
   260→    if (!medication) {
   261→      throw new ActionError("Medication not found");
   262→    }
   263→
   264→    if (medication.userId !== user.id) {
   265→      throw new ActionError("You can only skip your own medications");
   266→    }
   267→
   268→    const intake = await prisma.medIntake.create({
   269→      data: {
   270→        medicationId,
   271→        takenAt: new Date(),
