   280→export const deleteMedIntake = authAction
   281→  .inputSchema(deleteIntakeSchema)
   282→  .action(async ({ parsedInput: { intakeId }, ctx: { user } }) => {
   283→    // Verify ownership through medication
   284→    const intake = await prisma.medIntake.findUnique({
   285→      where: { id: intakeId },
   286→      include: {
   287→        medication: {
   288→          select: { userId: true },
   289→        },
   290→      },
   291→    });
   292→
   293→    if (!intake) {
   294→      throw new ActionError("Intake not found");
