   296→
   297→    if (intake.medication.userId !== user.id) {
   298→      throw new ActionError("You can only delete your own intake records");
   299→    }
   300→
   301→    await prisma.medIntake.delete({
   302→      where: { id: intakeId },
   303→    });
   304→
   305→    return { success: true };
   306→  });
