    67→export const getDashboardSummary = authAction.action(
    68→  async ({ ctx: { user } }) => {
    69→    const now = new Date();
    70→    const startOfDay = new Date(now);
    71→    startOfDay.setHours(0, 0, 0, 0);
    72→
    73→    const startOfWeek = new Date(now);
    74→    startOfWeek.setDate(now.getDate() - 7);
    75→
    76→    const startOfMonth = new Date(now);
    77→    startOfMonth.setDate(now.getDate() - 30);
    78→
    79→    // Mood data (last 7 days for mini chart)
    80→    const moodEntries = await prisma.moodEntry.findMany({
    81→      where: {
    82→        userId: user.id,
