    84→      },
    85→      orderBy: { createdAt: "asc" },
    86→      select: { value: true, createdAt: true },
    87→    });
    88→
    89→    const weeklyMoodAvg =
    90→      moodEntries.length > 0
    91→        ? moodEntries.reduce((sum, e) => sum + e.value, 0) / moodEntries.length
    92→        : null;
    93→
    94→    // Medication adherence
    95→    const medications = await prisma.medication.findMany({
    96→      where: {
    97→        userId: user.id,
    98→        isArchived: false,
    99→        frequency: { not: "prn" },
   100→      },
   101→      include: {
   102→        intakes: {
   103→          where: {
   104→            takenAt: { gte: startOfMonth },
   105→            skipped: false,
   106→          },
   107→        },
   108→      },
   109→    });
   110→
   111→    // Calculate expected doses and actual taken
   112→    const totalMeds = medications.length;
   113→    const todayIntakes = await prisma.medIntake.count({
   114→      where: {
   115→        medication: { userId: user.id, isArchived: false },
   116→        takenAt: { gte: startOfDay },
   117→        skipped: false,
   118→      },
   119→    });
   120→
   121→    // Calculate monthly adherence (simplistic: taken / (meds * 30 days))
   122→    const monthlyIntakes = medications.reduce(
   123→      (sum, m) => sum + m.intakes.length,
   124→      0,
   125→    );
   126→    const expectedMonthly = totalMeds * 30;
   127→    const adherencePercent =
   128→      expectedMonthly > 0
   129→        ? Math.min(100, Math.round((monthlyIntakes / expectedMonthly) * 100))
   130→        : null;
   131→
   132→    // Therapy sessions (last session + count this month)
   133→    const lastTherapySession = await prisma.therapySession.findFirst({
   134→      where: { userId: user.id },
