   154→    const activeExercises = await prisma.exercise.count({
   155→      where: {
   156→        userId: user.id,
   157→        isArchived: false,
   158→      },
   159→    });
   160→
   161→    return {
   162→      mood: {
   163→        weeklyAverage: weeklyMoodAvg
   164→          ? Math.round(weeklyMoodAvg * 10) / 10
   165→          : null,
   166→        entries: moodEntries.map((e) => ({
   167→          value: e.value,
   168→          date: e.createdAt.toISOString(),
