     8→export const uploadImageAction = authAction
     9→  .inputSchema(
    10→    z.object({
    11→      formData: z.instanceof(FormData),
    12→    }),
    13→  )
    14→  .action(async ({ parsedInput: { formData } }) => {
    15→    const files = formData.get("files") as File | File[];
    16→
    17→    let file: File;
    18→
    19→    if (Array.isArray(files)) {
    20→      file = files[0];
    21→    } else {
    22→      file = files;
    23→    }
    24→
    25→    if (!(file instanceof File)) {
    26→      throw new ActionError("Invalid file (not a file)");
    27→    }
    28→
    29→    // If file is not an image throw an error
    30→    if (!file.type.startsWith("image/")) {
    31→      throw new ActionError("Invalid file (only images are allowed)");
    32→    }
    33→
    34→    // If file is too large throw an error (max 2mb)
    35→    if (file.size > 2 * 1024 * 1024) {
    36→      throw new ActionError("File too large (max 2mb)");
    37→    }
    38→
    39→    const response = await fileAdapter.uploadFile({
    40→      file,
    41→      path: "images",
    42→    });
    43→
    44→    if (response.error) {
    45→      throw new ActionError(response.error.message);
    46→    }
    47→
