    11→
    12→export const getExportData = authAction
    13→  .inputSchema(getExportDataSchema)
    14→  .action(async ({ parsedInput: { startDate, endDate }, ctx: { user } }) => {
    15→    const start = new Date(startDate);
    16→    start.setHours(0, 0, 0, 0);
    17→
    18→    const end = new Date(endDate);
    19→    end.setHours(23, 59, 59, 999);
    20→
    21→    // Get mood entries
    22→    const moodEntries = await prisma.moodEntry.findMany({
    23→      where: {
    24→        userId: user.id,
    25→        createdAt: { gte: start, lte: end },
    26→      },
    27→      orderBy: { createdAt: "asc" },
    28→      select: {
    29→        value: true,
    30→        note: true,
    31→        createdAt: true,
    32→      },
    33→    });
    34→
    35→    // Get medications and their intakes
    36→    const medications = await prisma.medication.findMany({
    37→      where: {
    38→        userId: user.id,
    39→      },
    40→      include: {
    41→        intakes: {
    42→          where: {
    43→            takenAt: { gte: start, lte: end },
    44→          },
    45→          orderBy: { takenAt: "asc" },
    46→        },
    47→        history: {
    48→          where: {
    49→            changedAt: { gte: start, lte: end },
    50→          },
    51→          orderBy: { changedAt: "asc" },
    52→        },
    53→      },
    54→    });
    55→
    56→    // Get therapy sessions
    57→    const therapySessions = await prisma.therapySession.findMany({
    58→      where: {
    59→        userId: user.id,
    60→        date: { gte: start, lte: end },
    61→      },
    62→      orderBy: { date: "asc" },
    63→      select: {
    64→        date: true,
    65→        notes: true,
    66→        benefitRating: true,
    67→      },
    68→    });
    69→
    70→    // Get exercise logs
    71→    const exerciseLogs = await prisma.exerciseLog.findMany({
    72→      where: {
    73→        exercise: { userId: user.id },
    74→        completedAt: { gte: start, lte: end },
    75→      },
    76→      include: {
    77→        exercise: {
    78→          select: { name: true },
    79→        },
    80→      },
    81→      orderBy: { completedAt: "asc" },
    82→    });
    83→
    84→    // Calculate summary stats
    85→    const moodAvg =
    86→      moodEntries.length > 0
    87→        ? moodEntries.reduce((sum, e) => sum + e.value, 0) / moodEntries.length
    88→        : null;
    89→
    90→    const moodMin =
    91→      moodEntries.length > 0
    92→        ? Math.min(...moodEntries.map((e) => e.value))
    93→        : null;
    94→
    95→    const moodMax =
    96→      moodEntries.length > 0
    97→        ? Math.max(...moodEntries.map((e) => e.value))
    98→        : null;
    99→
   100→    // Medication adherence
   101→    const regularMeds = medications.filter(
   102→      (m) => !m.isArchived && m.frequency !== "prn",
   103→    );
   104→    const totalExpectedDoses =
   105→      regularMeds.length *
   106→      Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
   107→    const totalTakenDoses = regularMeds.reduce(
   108→      (sum, m) => sum + m.intakes.filter((i) => !i.skipped).length,
   109→      0,
   110→    );
   111→    const adherencePercent =
   112→      totalExpectedDoses > 0
   113→        ? Math.min(
   114→            100,
   115→            Math.round((totalTakenDoses / totalExpectedDoses) * 100),
   116→          )
   117→        : null;
   118→
   119→    return {
   120→      period: {
   121→        start: start.toISOString(),
   122→        end: end.toISOString(),
   123→      },
   124→      userName: user.name || "Patient",
   125→      mood: {
   126→        entries: moodEntries.map((e) => ({
   127→          value: e.value,
   128→          note: e.note,
   129→          date: e.createdAt.toISOString(),
   130→        })),
   131→        stats: {
   132→          average: moodAvg ? Math.round(moodAvg * 10) / 10 : null,
   133→          min: moodMin,
   134→          max: moodMax,
   135→          count: moodEntries.length,
   136→        },
   137→      },
   138→      medications: {
   139→        list: medications
   140→          .filter((m) => !m.isArchived)
   141→          .map((m) => ({
   142→            name: m.name,
   143→            dosage: m.dosage,
   144→            frequency: m.frequency,
   145→            isPRN: m.isPRN,
   146→            intakesCount: m.intakes.filter((i) => !i.skipped).length,
   147→            dosageChanges: m.history.map((h) => ({
   148→              date: h.changedAt.toISOString(),
   149→              from: h.previousDosage,
   150→              to: h.dosage,
   151→            })),
   152→          })),
   153→        adherencePercent,
   154→      },
   155→      therapy: {
